import java.util.*;

class Solution {
    public int lightestDrop(int[][] grid) {
        int n = grid.length;
        int[] prev = grid[0].clone();          // best totals ending in the previous row
        for (int r = 1; r < n; r++) {
            int[] cur = new int[n];
            for (int c = 0; c < n; c++) {
                int best = prev[c];                              // straight down
                if (c > 0) best = Math.min(best, prev[c - 1]);   // from upper-left
                if (c < n - 1) best = Math.min(best, prev[c + 1]); // from upper-right
                cur[c] = grid[r][c] + best;
            }
            prev = cur;
        }
        int ans = Integer.MAX_VALUE;
        for (int v : prev) ans = Math.min(ans, v);
        return ans;
    }
}

