class Solution:
    def lightestDrop(self, grid: List[List[int]]) -> int:
        n = len(grid); b = grid[0][:]
        for r in range(1, n):
            b = [grid[r][c] + min(b[max(0, c - 1):c + 2]) for c in range(n)]
        return min(b)

