function lightestDrop(grid) {
  const n = grid.length; let b = grid[0].slice();
  for (let r = 1; r < n; r++) {
    const nb = new Array(n);
    for (let c = 0; c < n; c++) { let m = b[c]; if (c > 0) m = Math.min(m, b[c - 1]); if (c < n - 1) m = Math.min(m, b[c + 1]); nb[c] = grid[r][c] + m; }
    b = nb;
  }
  return Math.min(...b);
}
